LANGS = ["pt", "fr", "it", "de", "ru"]
d = json.load(open(R / "assets/data/activos_publicos.json", encoding="utf8"))
faltan, sql = [], []
for r in d:
    tr = dict(r.get("traduccion") or {})
    for i, l in enumerate(LANGS):
        o = {}
        if r.get("descripcion"):
            if r["referencia"] in DESC: o["descripcion"] = DESC[r["referencia"]][i]
            else: faltan.append(r["referencia"])
        h = r.get("habitaciones")
        if h and not h.isdigit():
            o["habitaciones"] = HAB[h][i] if h in HAB else h      # rangos numéricos: iguales
        tr[l] = o
    r["traduccion"] = tr
    sql.append("update public.activos set traduccion = '" + json.dumps(tr, ensure_ascii=False).replace("'", "''") +
               "'::jsonb where referencia = '" + r["referencia"].replace("'", "''") + "';")
assert not faltan, faltan
(R / "sql/03_traducciones.sql").write_text("-- Traducciones PT/FR/IT/DE/RU (manteniendo EN)\n" + "\n".join(sql) + "\n", encoding="utf8")
json.dump(d, open(R / "assets/data/activos_publicos.json", "w", encoding="utf8"), ensure_ascii=False, indent=1)
print("ok", len(sql))
